(function(window, document) {
    'use strict';

    // 1. ESCUDO ANTI-INSPECCION Y PROTECCION FRONT-END
    (function() {
        var noop = function() {};
        try {
            window.console.log = noop;
            window.console.info = noop;
            window.console.warn = noop;
            window.console.debug = noop;
            window.console.trace = noop;
            window.console.table = noop;
        } catch(_) {}

        document.addEventListener('contextmenu', function(e) {
            e.preventDefault();
            return false;
        }, { capture: true });

        document.addEventListener('keydown', function(e) {
            if (e.key === 'F12' || e.keyCode === 123) {
                e.preventDefault();
                e.stopPropagation();
                return false;
            }
            if (e.ctrlKey && (e.key === 'u' || e.key === 'U' || e.key === 's' || e.key === 'S' || 
                (e.shiftKey && (e.key === 'I' || e.key === 'i' || e.key === 'J' || e.key === 'j' || e.key === 'C' || e.key === 'c')))) {
                e.preventDefault();
                e.stopPropagation();
                return false;
            }
        }, { capture: true });
    })();

    // 2. EXTRACCION SEGURA DE PAYLOAD EN MEMORIA PRIVADA
    var serviceHistories = {};
    var siteHistories = {};
    var deviceHistories = {};
    var pEl = document.getElementById('monit-payload');
    if (pEl) {
        try {
            var parsed = JSON.parse(pEl.textContent || '{}');
            serviceHistories = parsed.s || {};
            siteHistories = parsed.t || {};
            deviceHistories = parsed.d || {};
        } catch(_) {}
        if (pEl.parentNode) {
            pEl.parentNode.removeChild(pEl);
        }
    }

    // 3. GESTION DEL TOOLTIP HUD EMERGENTE CON CHART.JS
    var tooltip = document.getElementById('tech-tooltip');
    var ttTitle = document.getElementById('tt-title');
    var ttType = document.getElementById('tt-type');
    var ttIp = document.getElementById('tt-ip');
    var ttPort = document.getElementById('tt-port');
    var ttProtocol = document.getElementById('tt-protocol');
    var ttLatency = document.getElementById('tt-latency');
    var ttStatus = document.getElementById('tt-status');
    var ttDetails = document.getElementById('tt-details');
    var sparklineChart = null;

    function renderSparklineChart(historyData, isUp) {
        var canvas = document.getElementById('tt-canvas');
        var noChartEl = document.getElementById('tt-no-chart');
        var uptimeBadge = document.getElementById('tt-uptime-badge');
        var statMin = document.getElementById('tt-stat-min');
        var statAvg = document.getElementById('tt-stat-avg');
        var statMax = document.getElementById('tt-stat-max');

        if (!canvas) return;

        var hasValidData = historyData && historyData.has_data;

        if (!hasValidData) {
            if (sparklineChart) {
                sparklineChart.destroy();
                sparklineChart = null;
            }
            canvas.style.display = 'none';
            if (noChartEl) {
                noChartEl.style.display = 'flex';
                if (isUp) {
                    noChartEl.innerHTML = '<div class="flex items-center justify-center gap-1.5 text-cyan-400 py-3"><span class="material-symbols-outlined text-base animate-pulse">sensors</span><span class="text-[9.5px] font-bold tracking-wide">ENLACE OPERATIVO / ACUMULANDO HISTÓRICO</span></div>';
                } else {
                    noChartEl.innerHTML = '<div class="flex items-center justify-center gap-1.5 text-red-400 py-3"><span class="material-symbols-outlined text-base">cloud_off</span><span class="text-[9.5px] font-bold tracking-wide">SIN TELEMETRÍA / ENLACE FUERA DE SERVICIO</span></div>';
                }
            }
            if (uptimeBadge) {
                if (isUp) {
                    uptimeBadge.innerText = '100% Up';
                    uptimeBadge.className = 'px-1.5 py-0.2 rounded text-[8.5px] font-bold font-mono bg-emerald-950/90 text-emerald-400 border border-emerald-500/40';
                } else {
                    uptimeBadge.innerText = '0% Up (24h)';
                    uptimeBadge.className = 'px-1.5 py-0.2 rounded text-[8.5px] font-bold font-mono bg-red-950/90 text-red-400 border border-red-500/50';
                }
            }
            if (statMin) statMin.innerText = isUp ? '< 1ms' : '--';
            if (statAvg) statAvg.innerText = isUp ? '< 1ms' : '--';
            if (statMax) statMax.innerText = isUp ? '< 1ms' : '--';
            return;
        }

        canvas.style.display = 'block';
        if (noChartEl) noChartEl.style.display = 'none';

        var labels = historyData.labels || [];
        var dataPoints = historyData.latencies || [];
        var statuses = historyData.statuses || [];
        var uptime = historyData.uptime_pct !== undefined ? historyData.uptime_pct : (isUp ? 100 : 0);
        var downCount = historyData.down_checks || 0;

        if (uptimeBadge) {
            if (downCount > 0) {
                uptimeBadge.innerText = uptime + '% Up (' + downCount + ' Caídas)';
                uptimeBadge.className = 'px-1.5 py-0.2 rounded text-[8.5px] font-bold font-mono bg-red-950/90 text-red-400 border border-red-500/40 glow-red';
            } else {
                uptimeBadge.innerText = uptime + '% Up (24h)';
                uptimeBadge.className = 'px-1.5 py-0.2 rounded text-[8.5px] font-bold font-mono bg-emerald-950/90 text-emerald-400 border border-emerald-500/40';
            }
        }

        if (statMin) statMin.innerText = (historyData.min_latency || 0) + 'ms';
        if (statAvg) statAvg.innerText = (historyData.avg_latency || 0) + 'ms';
        if (statMax) statMax.innerText = (historyData.max_latency || 0) + 'ms';

        var ctx = canvas.getContext('2d');
        var lineColor = isUp ? '#22d3ee' : '#ef4444';
        
        var gradient = ctx.createLinearGradient(0, 0, 0, 70);
        if (isUp) {
            gradient.addColorStop(0, 'rgba(34, 211, 238, 0.35)');
            gradient.addColorStop(1, 'rgba(34, 211, 238, 0.0)');
        } else {
            gradient.addColorStop(0, 'rgba(239, 68, 68, 0.35)');
            gradient.addColorStop(1, 'rgba(239, 68, 68, 0.0)');
        }

        var pointBackgroundColors = statuses.map(function(s) { return s === 1 ? '#22d3ee' : '#ef4444'; });
        var pointBorderColors = statuses.map(function(s) { return s === 1 ? '#051424' : '#fee2e2'; });
        var pointRadiuses = statuses.map(function(s) { return s === 1 ? 0 : 4; });
        var pointHoverRadiuses = statuses.map(function(s) { return s === 1 ? 4 : 7; });

        if (sparklineChart) {
            sparklineChart.destroy();
        }

        sparklineChart = new Chart(ctx, {
            type: 'line',
            data: {
                labels: labels,
                datasets: [{
                    data: dataPoints,
                    borderColor: lineColor,
                    borderWidth: 1.5,
                    backgroundColor: gradient,
                    fill: true,
                    tension: 0.25,
                    pointRadius: pointRadiuses,
                    pointHoverRadius: pointHoverRadiuses,
                    pointHitRadius: 10,
                    pointBackgroundColor: pointBackgroundColors,
                    pointBorderColor: pointBorderColors,
                    pointBorderWidth: 1.2,
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                animation: false,
                interaction: {
                    intersect: false,
                    mode: 'index',
                },
                plugins: {
                    legend: { display: false },
                    tooltip: {
                        enabled: true,
                        displayColors: false,
                        padding: 4,
                        bodyFont: { size: 9, family: 'monospace' },
                        callbacks: {
                            title: function(items) { return items.length ? 'Hora: ' + items[0].label : ''; },
                            label: function(c) {
                                var idx = c.dataIndex;
                                if (statuses[idx] === 0) {
                                    return '🚨 CAÍDA / TIMEOUT (0 ms)';
                                }
                                return 'Latencia: ' + c.parsed.y + ' ms';
                            }
                        }
                    }
                },
                scales: {
                    x: {
                        display: true,
                        grid: { display: false },
                        ticks: {
                            color: '#64748b',
                            font: { size: 7.5, family: 'monospace' },
                            maxTicksLimit: 6
                        }
                    },
                    y: {
                        display: true,
                        grid: { color: 'rgba(255,255,255,0.05)' },
                        ticks: {
                            color: '#64748b',
                            font: { size: 7.5, family: 'monospace' },
                            maxTicksLimit: 3,
                            callback: function(v) { return v + 'ms'; }
                        }
                    }
                }
            }
        });
    }

    function attachTooltipEvents() {
        document.querySelectorAll('[data-tech-title]').forEach(function(el) {
            if (el._hasTooltip) return;
            el._hasTooltip = true;

            el.addEventListener('mouseenter', function(e) {
                var authBlock = document.getElementById('tt-auth-required-block');
                var fullBlock = document.getElementById('tt-authenticated-block');
                var authTargetName = document.getElementById('tt-auth-target-name');

                if (!window._isAuth) {
                    if (fullBlock) fullBlock.style.display = 'none';
                    if (authBlock) {
                        authBlock.classList.remove('hidden');
                        authBlock.style.display = 'flex';
                    }
                    if (authTargetName) {
                        authTargetName.innerText = el.getAttribute('data-tech-title') || 'Acceso Restringido';
                    }
                    if (tooltip) {
                        tooltip.classList.add('show');
                        positionTooltip(e);
                    }
                    return;
                }

                if (authBlock) {
                    authBlock.classList.add('hidden');
                    authBlock.style.display = 'none';
                }
                if (fullBlock) fullBlock.style.display = 'block';

                if (ttTitle) ttTitle.innerText = el.getAttribute('data-tech-title') || 'DETALLE TÉCNICO';
                if (ttType) ttType.innerText = el.getAttribute('data-tech-type') || 'GENERAL';
                if (ttIp) ttIp.innerText = el.getAttribute('data-tech-ip') || '--';
                if (ttPort) ttPort.innerText = el.getAttribute('data-tech-port') || '--';
                if (ttProtocol) ttProtocol.innerText = el.getAttribute('data-tech-protocol') || 'TCP/IP';
                if (ttLatency) ttLatency.innerText = el.getAttribute('data-tech-latency') || '--';
                
                var status = el.getAttribute('data-tech-status') || 'ACTIVO';
                if (ttStatus) {
                    ttStatus.innerText = status;
                    var isItemUp = status.includes('OPERATIVO') || status.includes('ACTIVO') || status.includes('ONLINE');
                    ttStatus.className = isItemUp 
                        ? 'font-bold text-emerald-400 truncate max-w-[160px]' 
                        : 'font-bold text-red-400 truncate max-w-[160px]';
                }

                if (ttDetails) ttDetails.innerText = el.getAttribute('data-tech-details') || 'Monitoreo continuo cada 5 min.';

                var chartContainer = document.getElementById('tt-chart-container');
                var id = el.getAttribute('data-tech-id');
                var kind = el.getAttribute('data-tech-kind');

                if (!id || !kind) {
                    if (chartContainer) chartContainer.style.display = 'none';
                    if (sparklineChart) {
                        sparklineChart.destroy();
                        sparklineChart = null;
                    }
                } else {
                    if (chartContainer) chartContainer.style.display = 'block';
                    var hist = null;
                    if (kind === 'site') {
                        hist = siteHistories[id] || null;
                    } else if (kind === 'device') {
                        hist = deviceHistories[id] || null;
                    } else {
                        hist = serviceHistories[id] || null;
                    }
                    renderSparklineChart(hist, isItemUp);
                }

                if (tooltip) {
                    tooltip.classList.add('show');
                    positionTooltip(e);
                }
            });

            el.addEventListener('mousemove', function(e) {
                positionTooltip(e);
            });

            el.addEventListener('mouseleave', function() {
                if (tooltip) tooltip.classList.remove('show');
            });
        });
    }

    function attachCardClickEvents() {
        document.querySelectorAll('.item-searchable, [data-tech-title]').forEach(function(el) {
            if (el._hasAuthClick) return;
            el._hasAuthClick = true;

            el.addEventListener('click', function(e) {
                if (!window._isAuth) {
                    if (e.target.closest('button') || e.target.closest('a')) {
                        return;
                    }
                    if (el.hasAttribute('onclick') && el.getAttribute('onclick').includes('toggleSiteDetails')) {
                        return;
                    }
                    e.preventDefault();
                    e.stopPropagation();
                    var title = el.getAttribute('data-tech-title') || 'Servicio o Sede';
                    if (typeof window.showItemAuthModal === 'function') {
                        window.showItemAuthModal(title);
                    }
                }
            });
        });
    }

    if (!window.showItemAuthModal) {
        window.showItemAuthModal = function(title) {
            if (tooltip) tooltip.classList.remove('show');
            var m = document.getElementById('modal-item-auth-prompt');
            var t = document.getElementById('item-auth-prompt-target');
            if (t && title) t.innerText = title;
            if (m) {
                m.classList.remove('hidden');
                m.classList.add('flex');
            }
        };
    }
    if (!window.closeItemAuthModal) {
        window.closeItemAuthModal = function() {
            var m = document.getElementById('modal-item-auth-prompt');
            if (m) {
                m.classList.remove('flex');
                m.classList.add('hidden');
            }
        };
    }
    window.showAuthRequiredModal = window.showItemAuthModal;
    window.closeAuthRequiredModal = window.closeItemAuthModal;

    function positionTooltip(e) {
        if (!tooltip) return;
        var padding = 15;
        var x = e.clientX + padding;
        var y = e.clientY + padding;
        var ttWidth = 330;
        var ttHeight = 310;

        if (x + ttWidth > window.innerWidth) {
            x = e.clientX - ttWidth - padding;
        }
        if (y + ttHeight > window.innerHeight) {
            y = e.clientY - ttHeight - padding;
        }

        tooltip.style.left = Math.max(10, x) + 'px';
        tooltip.style.top = Math.max(10, y) + 'px';
    }

    // 4. ACORDEON DESPLEGABLE DE EQUIPOS EN SEDE
    window.toggleSiteDetails = function(id, headerEl) {
        if (!window._isAuth) {
            var title = headerEl ? (headerEl.getAttribute('data-tech-title') || 'Sede Regional') : 'Sede Regional';
            if (typeof window.showItemAuthModal === 'function') {
                window.showItemAuthModal(title);
            }
            return;
        }
        var details = document.getElementById(id);
        var chevron = headerEl ? headerEl.querySelector('.chevron-icon') : null;
        if (!details) return;

        if (details.classList.contains('hidden')) {
            details.classList.remove('hidden');
            if (chevron) chevron.style.transform = 'rotate(180deg)';
        } else {
            details.classList.add('hidden');
            if (chevron) chevron.style.transform = 'rotate(0deg)';
        }
    };

    // 5. BUSQUEDA REACTIVA EN TIEMPO REAL
    window.filterLiveItems = function() {
        var input = document.getElementById('live-search-input');
        var query = (input && input.value ? input.value : '').toLowerCase();
        document.querySelectorAll('.item-searchable').forEach(function(el) {
            var searchData = el.getAttribute('data-search') || '';
            el.style.display = searchData.includes(query) ? '' : 'none';
        });
    };

    // 6. AUTO-REFRESCO ASINCRONO EN VIVO (CADA 15 SEGUNDOS)
    async function fetchLiveMonitoring() {
        try {
            var res = await fetch('/api/status');
            if (!res.ok) return;
            var data = await res.json();
            if (!data.success || !data.snapshot) return;

            var snap = data.snapshot;
            var services = snap.services || [];
            var sites = snap.sites || [];
            var proxies = snap.proxies || [];
            var summary = snap.summary || {};
            var globalStatus = data.global_status || snap.global_status || 'OPERACIONAL';

            var lastSync = document.getElementById('last-sync-time');
            if (lastSync && data.updated_at) {
                lastSync.innerText = data.updated_at.split(' ')[1] || data.updated_at;
            }

            var globalBadge = document.getElementById('global-status-badge');
            if (globalBadge) {
                globalBadge.className = 'hidden sm:flex items-center gap-2 px-3 py-1 rounded-full border text-xs font-mono font-semibold ' + (
                    globalStatus === 'OPERACIONAL' 
                        ? 'bg-emerald-950/60 text-emerald-400 border-emerald-500/50 glow-green' 
                        : (globalStatus === 'DEGRADADO' 
                            ? 'bg-amber-950/60 text-amber-400 border-amber-500/50' 
                            : 'bg-red-950/60 text-red-400 border-red-500/50 glow-red')
                );
                globalBadge.setAttribute('data-tech-status', globalStatus);
                globalBadge.innerHTML = '<span class="w-2 h-2 rounded-full ' + (
                    globalStatus === 'OPERACIONAL' ? 'bg-emerald-400 pulse-dot' : (globalStatus === 'DEGRADADO' ? 'bg-amber-400 pulse-dot' : 'bg-red-400 pulse-dot')
                ) + '"></span><span id="global-status-text">' + globalStatus + '</span>';
            }

            var activeServices = services.filter(function(s) { return s.is_up; });
            var downServices = services.filter(function(s) { return !s.is_up; });
            var activeSites = sites.filter(function(st) { return st.is_up; });
            var downSites = sites.filter(function(st) { return !st.is_up; });

            var activeSvcContainer = document.getElementById('active-services-container');
            var activeSvcBadge = document.getElementById('badge-count-active-services');
            if (activeSvcBadge) activeSvcBadge.innerText = activeServices.length + ' Operativos';

            if (activeSvcContainer) {
                if (activeServices.length === 0) {
                    activeSvcContainer.innerHTML = '<div class="p-8 text-center text-xs font-mono text-obsidian-muted">No hay servicios activos reportados en este momento.</div>';
                } else {
                    activeSvcContainer.innerHTML = activeServices.map(function(s) {
                        var targetHost = s.host_ip || s.web_url || '127.0.0.1';
                        var port = s.port || (s.type === 'WEB' ? '80/443' : (s.type === 'DNS' ? '53' : (s.type === 'SMTP' ? '25' : (s.type === 'LDAP' ? '389' : 'ICMP'))));
                        var protocol = s.type === 'WEB' ? 'HTTP/HTTPS GET Request' : (s.type === 'DNS' ? 'DNS Query' : (s.type === 'SMTP' ? 'SMTP Mail Handshake' : (s.type === 'LDAP' ? 'LDAP Bind Handshake' : 'ICMP Ping')));
                        var latencyStr = s.latency_ms > 0 ? (s.latency_ms + 'ms') : '<15ms';
                        var details = s.web_url ? ('Endpoint: ' + s.web_url) : 'Verificación por socket de transporte directo.';

                        var latencyHtml = window._isAuth 
                            ? ('<span class="text-[9px] font-mono text-emerald-400/90 font-medium">' + latencyStr + '</span>')
                            : ('<span class="text-[9px] font-mono text-amber-400/80 flex items-center gap-0.5" title="Inicie sesión para ver la latencia"><span class="material-symbols-outlined text-[11px]">lock</span></span>');

                        var techAttrs = window._isAuth
                            ? ('data-tech-ip="' + targetHost + '" data-tech-port="' + port + '" data-tech-protocol="' + protocol + '" data-tech-latency="' + latencyStr + '" data-tech-status="OPERATIVO (200 OK / Response)" data-tech-details="' + details + '" data-tech-id="' + s.id + '" data-tech-kind="service"')
                            : 'data-tech-auth-required="true"';

                        return '<div class="py-1.5 px-2.5 rounded-lg bg-obsidian-panel/60 hover:bg-obsidian-panel border border-obsidian-border/50 hover:border-emerald-500/50 transition cursor-pointer flex items-center justify-between group item-searchable select-none" data-search="' + (s.name + ' ' + s.type).toLowerCase() + '" data-tech-title="' + s.name + '" data-tech-type="' + s.type + '" ' + techAttrs + '><div class="flex items-center gap-2 min-w-0"><div class="w-1.5 h-1.5 rounded-full shrink-0 bg-emerald-400 glow-green"></div><span class="text-[11px] font-semibold text-white group-hover:text-emerald-300 transition-colors truncate">' + s.name + '</span></div><div class="flex items-center gap-1.5 shrink-0">' + latencyHtml + '<span class="px-1 py-0.5 rounded text-[8.5px] font-mono font-bold uppercase bg-obsidian-bg/80 border border-emerald-500/30 text-emerald-300">' + s.type + '</span></div></div>';
                    }).join('');
                }
            }

            var openAccordions = new Set();
            document.querySelectorAll('[id^=site-details-]').forEach(function(el) {
                if (!el.classList.contains('hidden')) {
                    openAccordions.add(el.id);
                }
            });

            var activeSitesContainer = document.getElementById('active-sites-container');
            var activeSitesBadge = document.getElementById('badge-count-active-sites');
            if (activeSitesBadge) activeSitesBadge.innerText = activeSites.length + ' Sedes Online';

            if (activeSitesContainer) {
                if (activeSites.length === 0) {
                    activeSitesContainer.innerHTML = '<div class="p-8 text-center text-xs font-mono text-obsidian-muted">No hay sedes conectadas en este momento.</div>';
                } else {
                    activeSitesContainer.innerHTML = activeSites.map(function(site) {
                        var isA = site.letter === 'A';
                        var latencyStr = site.latency_ms > 0 ? (site.latency_ms + ' ms') : '< 15 ms';
                        var cleanAddress = site.address && !site.address.toUpperCase().includes('NO CONFIGURADO') ? site.address : '';
                        var cleanPhone = site.phone_1 && !site.phone_1.toUpperCase().includes('NO CONFIGURADO') ? site.phone_1 : '';
                        var details = (cleanAddress ? 'Ubicación: ' + cleanAddress : 'Sede Regional Corporativa') + (cleanPhone ? ' • Contacto: ' + cleanPhone : '');
                        var isOpen = openAccordions.has('site-details-' + site.letter);

                        var devicesHtml = (site.devices && site.devices.length > 0) 
                            ? '<div class="space-y-1"><span class="text-[8.5px] uppercase font-mono tracking-wider text-obsidian-muted block">Equipos en Sitio (' + site.devices.length + ')</span><div class="grid grid-cols-1 sm:grid-cols-2 gap-1.5">' + site.devices.map(function(dev) {
                                var safeDevName = (dev.name || '').replace(/'/g, "\\'");
                                var safeSiteName = (site.name || '').replace(/'/g, "\\'");
                                var vncBtn = window._userCanVnc 
                                    ? '<button type="button" onclick="event.stopPropagation(); openVncModal(\'' + dev.ip + '\', \'' + safeDevName + '\', \'' + safeSiteName + '\', true)" class="px-1.5 py-0.5 rounded text-[8px] font-mono font-bold bg-cyan-950/90 hover:bg-obsidian-cyan hover:text-black border border-cyan-500/50 text-cyan-300 transition flex items-center gap-0.5 shrink-0 shadow-sm shadow-cyan-950 cursor-pointer" title="Conectar Escritorio Remoto VNC (' + dev.ip + ')"><span class="material-symbols-outlined text-[10px]">desktop_windows</span><span>VNC</span></button>'
                                    : '<button type="button" onclick="event.stopPropagation(); openVncModal(\'' + dev.ip + '\', \'' + safeDevName + '\', \'' + safeSiteName + '\', false)" class="px-1.5 py-0.5 rounded text-[8px] font-mono bg-obsidian-card/90 hover:bg-amber-950/40 border border-obsidian-border hover:border-amber-500/40 text-obsidian-muted hover:text-amber-300 transition flex items-center gap-0.5 shrink-0 cursor-pointer" title="Debe iniciar sesión para conectar por VNC"><span class="material-symbols-outlined text-[10px] text-amber-400/80">lock</span><span>VNC</span></button>';
                                return '<div class="bg-obsidian-panel/90 hover:bg-obsidian-panel border border-obsidian-border rounded p-1.5 flex items-center justify-between text-[9px] font-mono cursor-pointer transition hover:border-obsidian-cyan/40" data-tech-title="' + site.name + ' - ' + dev.name + '" data-tech-type="EQUIPO SECUNDARIO" data-tech-ip="' + dev.ip + '" data-tech-port="Slot #' + dev.device_number + '" data-tech-protocol="ICMP Echo Ping" data-tech-latency="' + (dev.is_up ? '< 10 ms' : '--') + '" data-tech-status="' + (dev.is_up ? 'ONLINE (Ping Respondido)' : 'OFFLINE (Inaccesible)') + '" data-tech-details="Dispositivo interno vinculado a la red local de ' + site.name + '." data-tech-id="' + site.id + '" data-tech-kind="site"><div class="flex items-center space-x-1.5 min-w-0 pr-1 truncate"><span class="w-1.5 h-1.5 rounded-full shrink-0 ' + (dev.is_up ? 'bg-emerald-400 glow-green' : 'bg-red-500') + '"></span><span class="text-white truncate" title="' + dev.name + '">' + dev.name + '</span></div>' + vncBtn + '</div>';
                            }).join('') + '</div></div>'
                            : '<p class="text-[9px] font-mono text-obsidian-muted text-center py-1">Sin equipos secundarios registrados</p>';

                        var siteTechAttrs = window._isAuth
                            ? ('data-tech-ip="' + (site.ip || '0.0.0.0') + '" data-tech-port="Gateway PING / ICMP" data-tech-protocol="Enlace de Transporte WAN" data-tech-latency="' + latencyStr + '" data-tech-status="ONLINE (Conectado / Operativo)" data-tech-details="' + details + '" data-tech-id="' + site.id + '" data-tech-kind="site"')
                            : 'data-tech-auth-required="true"';

                        var siteAccordionContent = window._isAuth
                            ? ('<div class="flex items-center justify-between text-[10px] font-mono bg-obsidian-bg/80 px-2 py-1 rounded-lg border border-obsidian-border/40"><span class="text-[9px] text-obsidian-muted">Latencia Gateway:</span><span class="font-bold text-emerald-400 text-[10px]">' + latencyStr + '</span></div>' + devicesHtml)
                            : ('<div class="p-3 text-center text-xs font-mono text-amber-300 bg-amber-950/20 rounded-lg border border-amber-500/30 space-y-1.5"><p class="font-bold flex items-center justify-center gap-1.5 text-white"><span class="material-symbols-outlined text-sm text-amber-400">lock</span><span>Acceso Restringido</span></p><p class="text-[11px] font-sans text-amber-200">Debe iniciar sesión para ver los datos del servicio o la sede en su defecto.</p></div>');

                        return '<div class="glass-card rounded-lg border border-obsidian-border/80 overflow-hidden group hover:border-obsidian-cyan/40 transition"><div class="p-2.5 flex items-center justify-between cursor-pointer select-none" onclick="toggleSiteDetails(\'site-details-' + site.letter + '\', this)" data-search="' + (site.name + ' ' + cleanAddress).toLowerCase() + '" data-tech-title="' + site.name + '" data-tech-type="SEDE REGIONAL" ' + siteTechAttrs + '><div class="flex items-center gap-2 min-w-0"><div class="w-1.5 h-1.5 rounded-full shrink-0 bg-emerald-400 glow-green"></div><div class="min-w-0"><h3 class="text-[11px] font-bold text-white group-hover:text-obsidian-cyan transition-colors truncate">' + site.name + '</h3><p class="text-[9px] font-mono text-obsidian-muted truncate">' + (cleanAddress ? cleanAddress.substring(0, 38) + (cleanAddress.length > 38 ? '...' : '') : 'Sede Regional Corporativa') + '</p></div></div><div class="flex items-center gap-1.5 shrink-0"><span class="px-1 py-0.5 rounded text-[8.5px] font-mono font-bold uppercase ' + (isA ? 'bg-obsidian-cyan/20 text-obsidian-cyan border border-obsidian-cyan/30' : 'bg-obsidian-purple/20 text-obsidian-purple border border-obsidian-purple/30') + '">' + (isA ? 'HUB' : 'SEDE') + '</span><span class="material-symbols-outlined text-obsidian-muted text-sm transition-transform duration-200 chevron-icon" style="' + (isOpen ? 'transform: rotate(180deg);' : '') + '">expand_more</span></div></div><div id="site-details-' + site.letter + '" class="' + (isOpen ? '' : 'hidden') + ' px-2.5 pb-2.5 pt-1 border-t border-obsidian-border/40 bg-obsidian-bg/40 space-y-2">' + siteAccordionContent + '</div></div>';
                    }).join('');
                }
            }

            var netDevices = snap.network_devices || [];
            var netDevContainer = document.getElementById('valle-seco-devices-container');
            var netDevBadge = document.getElementById('badge-count-valle-seco-devices');
            var netOnline = netDevices.filter(function(d) { return d.is_up; }).length;
            if (netDevBadge) {
                netDevBadge.innerText = netOnline + ' / ' + netDevices.length + ' Online';
            }
            if (netDevContainer && netDevices.length > 0) {
                netDevContainer.innerHTML = netDevices.map(function(d) {
                    var isUp = !!d.is_up;
                    var latStr = d.latency_ms > 0 ? (d.latency_ms + ' ms') : '< 1 ms';
                    var safeName = (d.name || '').replace(/'/g, "\\'");
                    var accessType = (d.access_type || 'SIN SOPORTE').toUpperCase().trim();
                    var accessPort = d.access_port || (accessType === 'TELNET' ? 23 : (accessType === 'WEB' ? 80 : 5900));
                    var canRemote = window._userCanRemote !== undefined ? window._userCanRemote : window._userCanVnc;
                    var actionBtn = '';

                    if (accessType === 'TELNET') {
                        actionBtn = canRemote
                            ? '<button type="button" onclick="event.stopPropagation(); openAccessModal(\'TELNET\', \'' + d.ip + '\', ' + accessPort + ', \'' + safeName + '\', \'Red Valle Seco\', true)" class="px-1.5 py-0.5 rounded text-[8px] font-mono font-bold bg-cyan-950/90 hover:bg-obsidian-cyan hover:text-black border border-cyan-500/50 text-cyan-300 transition flex items-center gap-0.5 shrink-0 shadow-sm shadow-cyan-950 cursor-pointer" title="Abrir Terminal Telnet (' + d.ip + ':' + accessPort + ')"><span class="material-symbols-outlined text-[10px]">terminal</span><span>TELNET</span></button>'
                            : '<button type="button" onclick="event.stopPropagation(); openAccessModal(\'TELNET\', \'' + d.ip + '\', ' + accessPort + ', \'' + safeName + '\', \'Red Valle Seco\', false)" class="px-1.5 py-0.5 rounded text-[8px] font-mono bg-obsidian-card/90 hover:bg-amber-950/40 border border-obsidian-border hover:border-amber-500/40 text-obsidian-muted hover:text-amber-300 transition flex items-center gap-0.5 shrink-0 cursor-pointer" title="Debe iniciar sesión para acceder por Telnet"><span class="material-symbols-outlined text-[10px] text-amber-400/80">lock</span><span>TELNET</span></button>';
                    } else if (accessType === 'WEB') {
                        actionBtn = canRemote
                            ? '<button type="button" onclick="event.stopPropagation(); openAccessModal(\'WEB\', \'' + d.ip + '\', ' + accessPort + ', \'' + safeName + '\', \'Red Valle Seco\', true)" class="px-1.5 py-0.5 rounded text-[8px] font-mono font-bold bg-cyan-950/90 hover:bg-obsidian-cyan hover:text-black border border-cyan-500/50 text-cyan-300 transition flex items-center gap-0.5 shrink-0 shadow-sm shadow-cyan-950 cursor-pointer" title="Abrir Panel Web (http://' + d.ip + ':' + accessPort + ')"><span class="material-symbols-outlined text-[10px]">language</span><span>WEB</span></button>'
                            : '<button type="button" onclick="event.stopPropagation(); openAccessModal(\'WEB\', \'' + d.ip + '\', ' + accessPort + ', \'' + safeName + '\', \'Red Valle Seco\', false)" class="px-1.5 py-0.5 rounded text-[8px] font-mono bg-obsidian-card/90 hover:bg-amber-950/40 border border-obsidian-border hover:border-amber-500/40 text-obsidian-muted hover:text-amber-300 transition flex items-center gap-0.5 shrink-0 cursor-pointer" title="Debe iniciar sesión para acceder al panel web"><span class="material-symbols-outlined text-[10px] text-amber-400/80">lock</span><span>WEB</span></button>';
                    } else if (accessType === 'VNC') {
                        actionBtn = canRemote
                            ? '<button type="button" onclick="event.stopPropagation(); openAccessModal(\'VNC\', \'' + d.ip + '\', ' + accessPort + ', \'' + safeName + '\', \'Red Valle Seco\', true)" class="px-1.5 py-0.5 rounded text-[8px] font-mono font-bold bg-cyan-950/90 hover:bg-obsidian-cyan hover:text-black border border-cyan-500/50 text-cyan-300 transition flex items-center gap-0.5 shrink-0 shadow-sm shadow-cyan-950 cursor-pointer" title="Conectar Escritorio Remoto VNC (' + d.ip + ')"><span class="material-symbols-outlined text-[10px]">desktop_windows</span><span>VNC</span></button>'
                            : '<button type="button" onclick="event.stopPropagation(); openAccessModal(\'VNC\', \'' + d.ip + '\', ' + accessPort + ', \'' + safeName + '\', \'Red Valle Seco\', false)" class="px-1.5 py-0.5 rounded text-[8px] font-mono bg-obsidian-card/90 hover:bg-amber-950/40 border border-obsidian-border hover:border-amber-500/40 text-obsidian-muted hover:text-amber-300 transition flex items-center gap-0.5 shrink-0 cursor-pointer" title="Debe iniciar sesión para conectar por VNC"><span class="material-symbols-outlined text-[10px] text-amber-400/80">lock</span><span>VNC</span></button>';
                    }
                    var vendorBadge = d.vendor_data ? '<span class="px-1 py-0.2 rounded text-[7.5px] font-mono text-obsidian-muted bg-obsidian-bg/80 border border-obsidian-border/40 truncate shrink-0">' + d.vendor_data + '</span>' : '';
                    var macText = d.mac ? (' • MAC: <span class="text-obsidian-cyan/70">' + d.mac + '</span>') : '';
                    var techPort = 'MAC: ' + (d.mac || 'No disponible') + (accessType !== 'SIN SOPORTE' ? ' • ' + accessType + ':' + accessPort : '');
                    var techDetails = (d.vendor_data ? 'Fabricante / Info: ' + d.vendor_data : 'Equipo de red local Valle Seco.') + (accessType !== 'SIN SOPORTE' ? ' • Acceso: ' + accessType : '');

                    var lanTechAttrs = window._isAuth
                        ? ('data-tech-ip="' + d.ip + '" data-tech-port="' + techPort + '" data-tech-protocol="ICMP Ping Directo" data-tech-latency="' + (isUp ? latStr : 'Timeout / Sin respuesta') + '" data-tech-status="' + (isUp ? 'OPERATIVO (Enlace Local LAN Activo)' : 'OFFLINE (Dispositivo no responde en LAN)') + '" data-tech-details="' + techDetails + '" data-tech-id="' + d.id + '" data-tech-kind="device"')
                        : 'data-tech-auth-required="true"';

                    return '<div class="py-1.5 px-2.5 rounded-lg bg-obsidian-panel/60 hover:bg-obsidian-panel border border-obsidian-border/60 hover:border-obsidian-cyan/50 transition cursor-pointer flex items-center justify-between group item-searchable select-none" data-search="' + (d.name + ' ' + d.ip + ' ' + (d.vendor_data || '')).toLowerCase() + '" data-tech-title="' + d.name + '" data-tech-type="DISPOSITIVO LAN VALLE SECO" ' + lanTechAttrs + '>' +
                        '<div class="flex items-center gap-2 min-w-0 pr-2">' +
                            '<div class="w-2 h-2 rounded-full shrink-0 ' + (isUp ? 'bg-emerald-400 glow-green' : 'bg-red-500') + '"></div>' +
                            '<div class="flex items-center gap-1.5 min-w-0 truncate">' +
                                '<h3 class="text-[11px] font-bold text-white group-hover:text-obsidian-cyan transition-colors truncate">' + d.name + '</h3>' +
                                vendorBadge +
                            '</div>' +
                        '</div>' +
                        '<div class="flex items-center gap-1.5 shrink-0">' +
                            actionBtn +
                        '</div>' +
                    '</div>';
                }).join('');
            }

            var downSvcContainer = document.getElementById('down-services-container');
            var downSvcBadge = document.getElementById('badge-count-down-services');
            if (downSvcBadge) {
                downSvcBadge.className = 'px-2 py-0.5 rounded text-[10px] font-mono font-bold ' + (
                    downServices.length > 0 ? 'bg-red-950 text-red-400 border border-red-500/50 glow-red' : 'bg-emerald-950 text-emerald-400 border border-emerald-500/40'
                );
                downSvcBadge.innerText = downServices.length + ' Inactivos';
            }

            if (downSvcContainer) {
                if (downServices.length === 0) {
                    downSvcContainer.innerHTML = '<div class="h-full flex flex-col items-center justify-center p-4 text-center"><span class="material-symbols-outlined text-emerald-400 text-2xl mb-1">verified</span><p class="text-xs font-mono text-emerald-400 font-bold">Todos los servicios operando normalmente</p><p class="text-[10px] font-mono text-obsidian-muted">Sin incidentes de aplicativo registrados</p></div>';
                } else {
                    downSvcContainer.innerHTML = downServices.map(function(s) {
                        var targetHost = s.host_ip || s.web_url || '127.0.0.1';
                        var port = s.port || (s.type === 'WEB' ? '80/443' : (s.type === 'DNS' ? '53' : (s.type === 'SMTP' ? '25' : (s.type === 'LDAP' ? '389' : 'ICMP'))));
                        var protocol = s.type === 'WEB' ? 'HTTP/HTTPS GET' : (s.type === 'DNS' ? 'DNS Query' : (s.type === 'SMTP' ? 'SMTP Mail' : (s.type === 'LDAP' ? 'LDAP Bind' : 'ICMP Ping')));
                        var details = s.web_url ? ('Endpoint: ' + s.web_url) : 'Sin respuesta de transporte de red.';

                        var downSvcTechAttrs = window._isAuth
                            ? ('data-tech-ip="' + targetHost + '" data-tech-port="' + port + '" data-tech-protocol="' + protocol + '" data-tech-latency="Timeout / Sin respuesta" data-tech-status="APAGADO (Host / Puerto inalcanzable)" data-tech-details="' + details + '" data-tech-id="' + s.id + '" data-tech-kind="service"')
                            : 'data-tech-auth-required="true"';

                        return '<div class="py-1.5 px-2.5 rounded-lg bg-red-950/30 hover:bg-red-950/50 border border-red-500/30 transition cursor-pointer flex items-center justify-between group item-searchable select-none" data-search="' + (s.name + ' ' + s.type).toLowerCase() + '" data-tech-title="' + s.name + '" data-tech-type="' + s.type + '" ' + downSvcTechAttrs + '><div class="flex items-center gap-2 min-w-0"><div class="w-1.5 h-1.5 rounded-full shrink-0 bg-red-500 glow-red"></div><span class="text-[11px] font-semibold text-red-200 group-hover:text-red-100 transition-colors truncate">' + s.name + '</span></div><div class="flex items-center gap-1.5 shrink-0"><span class="text-[9px] font-mono text-red-400/80 font-medium">Timeout</span><span class="px-1 py-0.5 rounded text-[8.5px] font-mono font-bold uppercase bg-red-950/80 border border-red-500/40 text-red-300">' + s.type + '</span></div></div>';
                    }).join('');
                }
            }

            var downSitesContainer = document.getElementById('down-sites-container');
            var downSitesBadge = document.getElementById('badge-count-down-sites');
            if (downSitesBadge) {
                downSitesBadge.className = 'px-2 py-0.5 rounded text-[10px] font-mono font-bold ' + (
                    downSites.length > 0 ? 'bg-red-950 text-red-400 border border-red-500/50 glow-red' : 'bg-emerald-950 text-emerald-400 border border-emerald-500/40'
                );
                downSitesBadge.innerText = downSites.length + ' Desconectadas';
            }

            if (downSitesContainer) {
                if (downSites.length === 0) {
                    downSitesContainer.innerHTML = '<div class="h-full flex flex-col items-center justify-center p-4 text-center"><span class="material-symbols-outlined text-emerald-400 text-2xl mb-1">wifi_tethering</span><p class="text-xs font-mono text-emerald-400 font-bold">Todos los enlaces regionales conectados</p><p class="text-[10px] font-mono text-obsidian-muted">Comunicación WAN 100% operativa</p></div>';
                } else {
                    downSitesContainer.innerHTML = downSites.map(function(site) {
                        var cleanAddress = site.address && !site.address.toUpperCase().includes('NO CONFIGURADO') ? site.address : '';
                        var cleanPhone = site.phone_1 && !site.phone_1.toUpperCase().includes('NO CONFIGURADO') ? site.phone_1 : '';
                        var details = (cleanAddress ? 'Ubicación: ' + cleanAddress : 'Sede Regional Corporativa') + (cleanPhone ? ' • Contacto: ' + cleanPhone : '');

                        var downSiteTechAttrs = window._isAuth
                            ? ('data-tech-ip="' + (site.ip || '0.0.0.0') + '" data-tech-port="Gateway PING / ICMP" data-tech-protocol="Enlace de Transporte WAN" data-tech-latency="100% Packet Loss" data-tech-status="ENLACE WAN CAÍDO" data-tech-details="' + details + '" data-tech-id="' + site.id + '" data-tech-kind="site"')
                            : 'data-tech-auth-required="true"';

                        return '<div class="py-1.5 px-2.5 rounded-lg bg-red-950/30 hover:bg-red-950/50 border border-red-500/30 transition cursor-pointer flex items-center justify-between group item-searchable select-none" data-search="' + (site.name + ' ' + cleanAddress).toLowerCase() + '" data-tech-title="' + site.name + '" data-tech-type="SEDE REGIONAL" ' + downSiteTechAttrs + '><div class="flex items-center gap-2 min-w-0"><div class="w-1.5 h-1.5 rounded-full shrink-0 bg-red-500 glow-red"></div><span class="text-[11px] font-semibold text-red-200 group-hover:text-red-100 transition-colors truncate">' + site.name + '</span></div><span class="px-1 py-0.5 rounded text-[8.5px] font-mono font-bold uppercase bg-red-950/80 border border-red-500/40 text-red-300">OFFLINE</span></div>';
                    }).join('');
                }
            }

            var totServ = services.length;
            var servUp = activeServices.length;
            var servPct = totServ > 0 ? Math.round((servUp / totServ) * 1000) / 10 : 100;
            var elServCount = document.getElementById('metric-services-count');
            var elServPct = document.getElementById('metric-services-pct');
            if (elServCount) elServCount.innerHTML = '<span class="text-xs font-bold text-white">' + servUp + '</span><span class="text-[9px] text-obsidian-muted">/ ' + totServ + '</span>';
            if (elServPct) {
                elServPct.innerText = servPct + '%';
                elServPct.className = 'text-[8.5px] font-mono font-bold ' + (servPct === 100 ? 'text-emerald-400' : (servPct >= 70 ? 'text-amber-400' : 'text-red-400'));
            }

            var totSites = sites.length;
            var sitesUp = activeSites.length;
            var sitesPct = totSites > 0 ? Math.round((sitesUp / totSites) * 1000) / 10 : 100;
            var elSitesCount = document.getElementById('metric-sites-count');
            var elSitesPct = document.getElementById('metric-sites-pct');
            if (elSitesCount) elSitesCount.innerHTML = '<span class="text-xs font-bold text-white">' + sitesUp + '</span><span class="text-[9px] text-obsidian-muted">/ ' + totSites + '</span>';
            if (elSitesPct) {
                elSitesPct.innerText = sitesPct + '%';
                elSitesPct.className = 'text-[8.5px] font-mono font-bold ' + (sitesPct === 100 ? 'text-emerald-400' : (sitesPct >= 70 ? 'text-amber-400' : 'text-red-400'));
            }

            var onlProxies = proxies.filter(function(p) { return p.is_up; }).length;
            var totProxies = proxies.length > 0 ? proxies.length : (snap.proxies_total || 4);
            var proxiesPct = totProxies > 0 ? Math.round((onlProxies / totProxies) * 1000) / 10 : 100;
            var elProxiesCount = document.getElementById('metric-proxies-count');
            var elProxiesPct = document.getElementById('metric-proxies-pct');
            if (elProxiesCount) elProxiesCount.innerHTML = '<span class="text-xs font-bold text-white">' + onlProxies + '</span><span class="text-[9px] text-obsidian-muted">/ ' + totProxies + '</span>';
            if (elProxiesPct) {
                elProxiesPct.innerText = proxiesPct + '%';
                elProxiesPct.className = 'text-[8.5px] font-mono font-bold ' + (proxiesPct === 100 ? 'text-emerald-400' : (proxiesPct >= 70 ? 'text-amber-400' : 'text-red-400'));
            }

            attachTooltipEvents();
            attachCardClickEvents();
        } catch(err) {}
    }

    // 7. INICIALIZACION
    document.addEventListener('DOMContentLoaded', function() {
        attachTooltipEvents();
        attachCardClickEvents();
        setInterval(fetchLiveMonitoring, 15000);
    });

})(window, document);
